import toast from 'react-hot-toast';
import Pagination from '../components/common/Pagination';
import InbreedingCalculatorModal from '../components/modules/InbreedingCalculatorModal';
import BatchExcelModal from '../components/modules/BatchExcelModal';
import CameraEarTagScanner from '../components/modules/CameraEarTagScanner';
