const SPECIES = ['Keçi', 'Koyun', 'Sığır', 'Manda', 'Deve'];
const STATUS_LABELS = { active: 'Aktif', sold: 'Satıldı', dead: 'Öldü', lost: 'Kayıp' };
const STATUS_COLORS = { active: 'badge-success', sold: 'badge-info', dead: 'badge-danger', lost: 'badge-warning' };

const formatDateForInput = (d) => {
  if (!d) return '';
  if (typeof d === 'string' && d.includes('T')) return d.split('T')[0];
  return String(d).slice(0, 10);
};

const formatDate = (dateStr) => {
  if (!dateStr) return '—';
  try {
    const d = new Date(dateStr);
    if (isNaN(d.getTime())) return String(dateStr).slice(0, 10);
    return d.toLocaleDateString('tr-TR', { year: 'numeric', month: 'short', day: 'numeric' });
  } catch {
    return String(dateStr).slice(0, 10);
  }
};

// Animal Ekleme / Düzenleme Hızlı Modalı
function AnimalModal({ animal, farmId, onClose, onSaved }) {
  const isEdit = !!animal;
  const todayStr = new Date().toISOString().split('T')[0];

  const [form, setForm] = useState(() => {
    if (animal) {
      return {
        name: animal.name || '',
        code: animal.code || '',
        species: animal.species || 'Keçi',
        breed: animal.breed || '',
        birth_date: formatDateForInput(animal.birth_date),
        gender: animal.gender || 'F',
        color_description: animal.color_description || '',
        current_weight: animal.current_weight != null ? animal.current_weight : '',
        status: animal.status || 'active',
        notes: animal.notes || ''
      };
    }
    return {
      name: '',
      code: '',
      species: 'Keçi',
      breed: '',
      birth_date: new Date().toISOString().split('T')[0],
      gender: 'F',
      color_description: '',
      current_weight: '',
      status: 'active',
      notes: ''
    };
  });
  const [saving, setSaving] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.name.trim() || !form.code.trim() || !form.birth_date) {
      toast.error('Ad, küpe no ve doğum tarihi zorunlu');
      return;
    }
    if (form.birth_date > todayStr) {
      toast.error('Doğum tarihi gelecekte bir tarih olamaz');
      return;
    }

    setSaving(true);
    try {
      const payload = {
        name: form.name.trim(),
        code: form.code.trim(),
        species: form.species,
        breed: form.breed?.trim() || null,
        birth_date: form.birth_date,
        gender: form.gender,
        color_description: form.color_description?.trim() || null,
        status: form.status,
        current_weight: form.current_weight !== '' && form.current_weight != null ? parseFloat(form.current_weight) : null,
        notes: form.notes?.trim() || null
      };

      if (isEdit) {
        await animalService.update(animal.id, farmId, payload);
        toast.success('Hayvan güncellendi');
      } else {
        await animalService.create(farmId, payload);
        toast.success('Hayvan eklendi');
      }
      onSaved();
      onClose();
    } catch (err) {
      toast.error(err.response?.data?.error || 'İşlem başarısız');
    } finally {
      setSaving(false);
    }
  };

  const f = (key, val) => setForm(prev => ({ ...prev, [key]: val }));

  return (
    <div className="fixed inset-0 bg-slate-950/70 backdrop-blur-md z-50 flex items-center justify-center p-3 sm:p-4 animate-fade-in">
      <div className="bg-white rounded-3xl shadow-2xl border border-slate-100 w-full max-w-lg max-h-[92vh] flex flex-col overflow-hidden">
        {/* Executive Header */}
        <div
          className="p-5 text-white flex items-center justify-between relative overflow-hidden"
          style={{ background: isEdit ? 'linear-gradient(135deg, #091e3a 0%, #1e3a8a 55%, #0f172a 100%)' : 'linear-gradient(135deg, #022c22 0%, #064e3b 50%, #0f172a 100%)' }}
        >
          <div className="absolute top-0 right-0 w-36 h-36 bg-white/5 rounded-full blur-2xl pointer-events-none" />
          <div className="flex items-center gap-3 relative z-10">
            <div className="w-11 h-11 rounded-2xl bg-white/10 backdrop-blur-md border border-white/20 flex items-center justify-center shadow-inner">
              {isEdit ? <Edit className="w-5 h-5 text-sky-300" /> : <Plus className="w-5 h-5 text-emerald-300" />}
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="font-bold text-white text-base">
                  {isEdit ? 'Hayvan Künyesi Düzenle' : 'Yeni Hayvan Kaydı'}
                </h3>
                <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-white/10 text-white/90 border border-white/20">
                  <Sparkles className="w-3 h-3 text-amber-300" /> {isEdit ? 'Güncelleme' : 'Hızlı Giriş'}
                </span>
              </div>
              <p className="text-xs text-white/70 mt-0.5">
                {isEdit ? `${animal.name} (${animal.code}) profil bilgileri` : 'Sürüye yeni hayvan tanımlayın'}
              </p>
            </div>
          </div>

          <button
            onClick={onClose}
            className="w-8 h-8 rounded-full bg-white/10 hover:bg-white/20 border border-white/15 text-white/80 hover:text-white flex items-center justify-center transition-all cursor-pointer relative z-10"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-5 space-y-4 overflow-y-auto [scrollbar-width:thin]">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1.5">Hayvan Adı <span className="text-rose-500">*</span></label>
              <input className="w-full text-xs font-semibold border-2 border-slate-200 rounded-xl px-3 py-2.5 focus:border-emerald-500 focus:outline-none transition" value={form.name} onChange={e => f('name', e.target.value)} placeholder="Örn: Çiçek" required />
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1.5">Küpe No <span className="text-rose-500">*</span></label>
              <input className="w-full text-xs font-mono font-bold border-2 border-slate-200 rounded-xl px-3 py-2.5 focus:border-emerald-500 focus:outline-none transition" value={form.code} onChange={e => f('code', e.target.value)} placeholder="Örn: TR-00123" required />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1.5">Tür <span className="text-rose-500">*</span></label>
              <select className="w-full text-xs font-semibold border-2 border-slate-200 rounded-xl px-3 py-2.5 focus:border-emerald-500 focus:outline-none bg-white transition" value={form.species} onChange={e => f('species', e.target.value)}>
                {SPECIES.map(s => <option key={s} value={s}>{s}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1.5">Irk</label>
              <input className="w-full text-xs font-semibold border-2 border-slate-200 rounded-xl px-3 py-2.5 focus:border-emerald-500 focus:outline-none transition" value={form.breed} onChange={e => f('breed', e.target.value)} placeholder="Örn: Saanen" />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1.5">Doğum Tarihi <span className="text-rose-500">*</span></label>
              <input type="date" max={todayStr} className="w-full text-xs font-semibold border-2 border-slate-200 rounded-xl px-3 py-2 focus:border-emerald-500 focus:outline-none transition bg-white" value={form.birth_date} onChange={e => f('birth_date', e.target.value)} required />
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1.5">Cinsiyet <span className="text-rose-500">*</span></label>
              <select className="w-full text-xs font-semibold border-2 border-slate-200 rounded-xl px-3 py-2 focus:border-emerald-500 focus:outline-none bg-white transition" value={form.gender} onChange={e => f('gender', e.target.value)}>
                <option value="F">♀ Dişi</option>
                <option value="M">♂ Erkek</option>
              </select>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1.5">Renk</label>
              <input className="w-full text-xs font-semibold border-2 border-slate-200 rounded-xl px-3 py-2 focus:border-emerald-500 focus:outline-none transition" value={form.color_description} onChange={e => f('color_description', e.target.value)} placeholder="Örn: Beyaz" />
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1.5">Canlı Ağırlık (kg)</label>
              <input type="number" step="0.1" min="0" className="w-full text-xs font-mono font-bold border-2 border-slate-200 rounded-xl px-3 py-2 focus:border-emerald-500 focus:outline-none transition" value={form.current_weight} onChange={e => f('current_weight', e.target.value)} placeholder="45.0" />
            </div>
          </div>

          {isEdit && (
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1.5">Sürü Durumu</label>
              <select className="w-full text-xs font-bold border-2 border-slate-200 rounded-xl px-3 py-2 focus:border-emerald-500 focus:outline-none bg-white transition" value={form.status} onChange={e => f('status', e.target.value)}>
                <option value="active">✅ Aktif Sürüde</option>
                <option value="sold">🏷️ Satıldı</option>
                <option value="dead">❌ Öldü / Kesim</option>
                <option value="lost">❓ Kayıp</option>
              </select>
            </div>
          )}

          <div>
            <label className="block text-xs font-bold text-slate-700 mb-1.5">Açıklama / Notlar</label>
            <textarea className="w-full text-xs border-2 border-slate-200 rounded-xl px-3 py-2 focus:border-emerald-500 focus:outline-none transition" rows={2} value={form.notes} onChange={e => f('notes', e.target.value)} placeholder="Pedigri, aşı ya da özel notlar..." />
          </div>

          <div className="flex gap-3 pt-2">
            <button type="button" onClick={onClose} className="flex-1 py-3 text-xs font-bold text-slate-600 bg-slate-100 hover:bg-slate-200 rounded-2xl transition">İptal</button>
            <button
              type="submit"
              disabled={saving}
              className="flex-1 py-3 text-xs font-bold text-white rounded-2xl shadow-md transition hover:brightness-110 disabled:opacity-50"
              style={{ background: isEdit ? 'linear-gradient(135deg, #0284c7 0%, #0369a1 100%)' : 'linear-gradient(135deg, #059669 0%, #047857 100%)' }}
            >
              {saving ? 'Kaydediliyor...' : (isEdit ? 'Değişiklikleri Güncelle' : 'Hayvanı Kaydet')}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

// Hayvan Çıkış / Durum Değişikliği Modalı (Executive Edition)
function ExitModal({ animal, farmId, onClose, onSaved }) {
  const [reason, setReason] = useState(animal.status === 'active' ? 'sold' : 'active');
  const [saving, setSaving] = useState(false);

  const handleConfirm = async () => {
    setSaving(true);
    try {
      await animalService.delete(animal.id, farmId, reason);
      toast.success(`Hayvan durumu güncellendi: ${STATUS_LABELS[reason] || reason}`);
      onSaved();
      onClose();
    } catch {
      toast.error('Çıkış işlemi başarısız');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-slate-950/70 backdrop-blur-md z-50 flex items-center justify-center p-3 sm:p-4 animate-fade-in">
      <div className="bg-white rounded-3xl shadow-2xl border border-slate-100 w-full max-w-md overflow-hidden flex flex-col">
        {/* Executive Header */}
        <div
          className="p-5 text-white flex items-center justify-between relative overflow-hidden"
          style={{ background: 'linear-gradient(135deg, #451a03 0%, #78350f 55%, #0f172a 100%)' }}
        >
          <div className="flex items-center gap-3 relative z-10">
            <div className="w-10 h-10 rounded-2xl bg-amber-500/20 border border-amber-400/30 flex items-center justify-center text-amber-300">
              <AlertTriangle className="w-5 h-5" />
            </div>
            <div>
              <h3 className="font-bold text-white text-base">Sürüden Çıkış / Durum Değiştir</h3>
              <p className="text-xs text-amber-200/80 mt-0.5">{animal.name} ({animal.code})</p>
            </div>
          </div>

          <button
            onClick={onClose}
            className="w-8 h-8 rounded-full bg-white/10 hover:bg-white/20 border border-white/15 text-white/80 hover:text-white flex items-center justify-center transition-all cursor-pointer relative z-10"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        <div className="p-5 space-y-4">
          <p className="text-xs text-slate-600 leading-relaxed">
            <strong className="text-slate-900 font-bold">{animal.name}</strong> küpeli hayvanın sürü durumunu güncellemek için gerekçeyi seçin:
          </p>

          <div className="space-y-2">
            <label className={`flex items-center gap-3 p-3.5 border-2 rounded-2xl cursor-pointer transition ${reason === 'sold' ? 'border-amber-500 bg-amber-50/70' : 'border-slate-200 hover:bg-slate-50'}`}>
              <input type="radio" name="exit_reason" value="sold" checked={reason === 'sold'} onChange={() => setReason('sold')} className="accent-amber-600" />
              <div>
                <p className="text-xs font-bold text-slate-900">🏷️ Satıldı (sold)</p>
                <p className="text-[11px] text-slate-500">Hayvan başka bir işletmeye veya kurbana satıldı</p>
              </div>
            </label>

            <label className={`flex items-center gap-3 p-3.5 border-2 rounded-2xl cursor-pointer transition ${reason === 'dead' ? 'border-rose-500 bg-rose-50/70' : 'border-slate-200 hover:bg-slate-50'}`}>
              <input type="radio" name="exit_reason" value="dead" checked={reason === 'dead'} onChange={() => setReason('dead')} className="accent-rose-600" />
              <div>
                <p className="text-xs font-bold text-slate-900">❌ Öldü / İtlaf / Zorunlu Kesim (dead)</p>
                <p className="text-[11px] text-slate-500">Doğal ölüm, hastalık veya kesimhane sevk</p>
              </div>
            </label>

            <label className={`flex items-center gap-3 p-3.5 border-2 rounded-2xl cursor-pointer transition ${reason === 'lost' ? 'border-indigo-500 bg-indigo-50/70' : 'border-slate-200 hover:bg-slate-50'}`}>
              <input type="radio" name="exit_reason" value="lost" checked={reason === 'lost'} onChange={() => setReason('lost')} className="accent-indigo-600" />
              <div>
                <p className="text-xs font-bold text-slate-900">❓ Kayıp / Çalındı (lost)</p>
                <p className="text-[11px] text-slate-500">Mera kaybı veya hırsızlık vakası</p>
              </div>
            </label>

            {animal.status !== 'active' && (
              <label className={`flex items-center gap-3 p-3.5 border-2 rounded-2xl cursor-pointer transition ${reason === 'active' ? 'border-emerald-500 bg-emerald-50/70' : 'border-slate-200 hover:bg-slate-50'}`}>
                <input type="radio" name="exit_reason" value="active" checked={reason === 'active'} onChange={() => setReason('active')} className="accent-emerald-600" />
                <div>
                  <p className="text-xs font-bold text-emerald-900">✅ Tekrar Aktifleştir (active)</p>
                  <p className="text-[11px] text-emerald-700">Hayvanı aktif sürü listesine geri al</p>
                </div>
              </label>
            )}
          </div>

          <div className="flex gap-3 pt-2">
            <button type="button" onClick={onClose} className="flex-1 py-3 text-xs font-bold text-slate-600 bg-slate-100 hover:bg-slate-200 rounded-2xl transition">İptal</button>
            <button
              type="button"
              disabled={saving}
              onClick={handleConfirm}
              className="flex-1 py-3 text-xs font-bold text-white rounded-2xl shadow-md transition hover:brightness-110 disabled:opacity-50"
              style={{ background: 'linear-gradient(135deg, #b91c1c 0%, #991b1b 100%)' }}
            >
              {saving ? 'İşleniyor...' : 'Onayla ve Değiştir'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

